    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool refResult = c.supportsInterface(interfaceId);
        // Buggy version (M) returns interfaceId == type(IERC165).interfaceId || super.supportsInterface(interfaceId)
        // The reference returns true for IERC1155 and IERC1155MetadataURI, but the bug returns false.
        // For any input where the reference returns true, the bug must also return true.
        // We can't call the buggy contract directly, so we embed the bug's logic as a pure function equivalent.
        // The buggy supportsInterface: interfaceId == type(IERC165).interfaceId || super.supportsInterface(interfaceId)
        // super.supportsInterface is ERC165.supportsInterface: interfaceId == type(IERC165).interfaceId
        // So buggy = interfaceId == type(IERC165).interfaceId
