pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool refResult = c.supportsInterface(interfaceId);
        // Reference: supportsInterface returns true iff interfaceId is type(IERC1155).interfaceId, type(IERC1155MetadataURI).interfaceId, or type(IERC165).interfaceId.
        // Bug: only returns true for type(IERC165).interfaceId.
        // Therefore, when refResult is true and interfaceId is not type(IERC165).interfaceId, the bug returns false.
        // The rule: for every interfaceId, if refResult is true and interfaceId != type(IERC165).interfaceId, then the bug result must also be true.
        // Equivalently: refResult && (interfaceId != type(IERC165).interfaceId) => false (assert that this scenario does NOT occur).
        // So we assert that it is NOT the case that (refResult && interfaceId != type(IERC165).interfaceId).
        assertTrue(!(refResult && interfaceId != type(IERC165).interfaceId));
    }
}

