import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // No vm.assume or bound needed; the fuzzer can explore the full bytes4 space.
        // If the interfaceId is exactly type(IERC1155MetadataURI).interfaceId,
        // the reference returns true and the mutant returns false.
        // The rule: for the IERC1155MetadataURI interface ID, reference is true, mutant is false.
        // The assertion captures the difference by comparing the return value of c.supportsInterface(interfaceId)
        // against the expected correct value (which is true if interfaceId equals that specific interface).
        // We define the expected correct value inline to avoid importing the interface.
        bytes4 target = bytes4(keccak256("IERC1155MetadataURI.uri.0e89341c")); // type(IERC1155MetadataURI).interfaceId
        bool expected = (interfaceId == target) ? true : c.supportsInterface(interfaceId);
        bool actual = c.supportsInterface(interfaceId);
        assertTrue(actual == expected);
    }
}

