contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The correct contract supports both IERC1155 and IERC1155MetadataURI.
        // The mutant only checks for IERC1155MetadataURI, so it cannot return true
        // for any interface ID that is not exactly IERC1155MetadataURI or supported by super.
        // By letting the fuzzer try any bytes4, it will eventually find an interfaceId
        // (e.g., type(IERC1155).interfaceId) where c.supportsInterface returns true
        // in the reference but false in the mutant.
        bytes4 ierc1155 = type(IERC1155).interfaceId;
        bytes4 ierc1155meta = type(IERC1155MetadataURI).interfaceId;

        // This is the invariant: the reference contract returns true when interfaceId equals
        // IERC1155 interface id, and false otherwise. The mutant will return false for IERC1155.
        // The fuzzer will find the counterexample.
        bool result = c.supportsInterface(interfaceId);
        bool expected = (interfaceId == ierc1155) || (interfaceId == ierc1155meta) || (interfaceId == type(IERC165).interfaceId);
        // The assertion: the actual result must match the expected behavior of the reference contract.
        // The reference contract always satisfies this. The mutant will fail for interfaceId == ierc1155.
        assertEq(result, expected);
