import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address actor, uint256 tokenId, uint256 mintAmount) public {
        vm.assume(actor != address(0));
        vm.assume(mintAmount > 0 && mintAmount <= type(uint128).max);
        vm.assume(tokenId <= type(uint64).max);

        // Create a game item so the tokenId can be minted
        c.createGameItem("test", "", false, true, 0, 0, 1);
        require(tokenId < c.allGameItemAttributes().length, "tokenId out of range");

        // Mint tokens to the actor
        vm.startPrank(address(this));
        c.mint(actor, tokenId, mintAmount);
        vm.stopPrank();

        uint256 balance = c.balanceOf(actor, tokenId);
        assertTrue(balance == mintAmount);
    }
}

